// Rust standard library: ownership helpers (mem, Rc, RefCell, Cell, Box), comparisons, char and f64 methods, ranges.
// Integer methods (checked_add, pow, ...) are generated by macros, so editors cannot jump to them reliably; skipped.
const { group, nums } = require('./kit.cjs');
const { list, add } = group({ at: ['core', '', /mem\/mod\.rs$/] });
const RC = ['alloc', 'Rc', /^src\/rc\.rs$/];
const REFCELL = ['core', 'RefCell', /^src\/cell\.rs$/];
const CELL = ['core', 'Cell', /^src\/cell\.rs$/];
const BOX = ['alloc', 'Box', /boxed\.rs$/];
const CMP = ['core', '', /^src\/cmp\.rs$/];
const CHAR = ['core', 'char', /char\/methods\.rs$/];
const F64 = ['core', 'f64', /num\/f64\.rs$/];
// sqrt, powi, round, floor, ceil and trunc are std methods (they may call the platform maths library)
const STD_F64 = ['std', 'f64', /num\/f64\.rs$/];
const RANGE = ['core', 'Range', /ops\/range\.rs$/];

add('mem/swap', 'swap', null, 'How mem::swap works', 'Exchanges the values of two variables without copying either.', {
  call: 'std::mem::swap(&mut a, &mut b);', note: 'a = "left", b = "right"', rows: [['a = "left"', 'b = "right"']], outs: ['a = "right"', 'b = "left"'],
  intro: 'swap takes two mutable references and trades their contents.',
  steps: [
    ['The value of a moves to b…', 0, 'o1'],
    ['…and the value of b moves to a, at the same time. No clone is made.', 1, 'o0'],
  ],
  result: 'a = "right", b = "left"', resultCap: 'Works for any type, even ones that cannot be copied or cloned.',
}, 'let mut a = String::from("left"); let mut b = String::from("right"); std::mem::swap(&mut a, &mut b); format!("a = {:?}, b = {:?}", a, b)');

add('mem/replace', 'replace', null, 'How mem::replace works', 'Puts a new value into a place and returns the old one.', {
  call: 'let old = std::mem::replace(&mut v, vec![9]);', note: 'v = [1, 2]', rows: [['v = [1, 2]']], outs: ['old = [1, 2]', 'v = [9]'],
  intro: 'You cannot move a value out of a &mut without putting something back. replace does both at once.',
  steps: [
    ['The old Vec [1, 2] is moved out and returned.', 0, 'o0'],
    ['The new Vec [9] takes its place, so v is never left empty.', 0, 'o1'],
  ],
  result: 'old = [1, 2], v = [9]', resultCap: 'Typical inside methods that take &mut self and need to take ownership of a field.',
}, 'let mut v = vec![1, 2]; let old = std::mem::replace(&mut v, vec![9]); format!("old = {:?}, v = {:?}", old, v)');

add('mem/take', 'take', null, 'How mem::take works', 'Moves a value out and leaves the type\'s default (empty) value behind.', {
  call: 'let items = std::mem::take(&mut self.items);', note: 'items = [1, 2, 3]', rows: [['items = [1, 2, 3]']], outs: ['taken: [1, 2, 3]', 'items: []'],
  intro: 'take is replace with the default value: an empty Vec, an empty String, 0.',
  steps: [
    ['The full Vec is moved out.', 0, 'o0'],
    ['An empty Vec is left in its place.', 0, 'o1'],
  ],
  result: 'taken = [1, 2, 3], left = []', resultCap: 'The type must implement Default. For Option, opt.take() does the same and leaves None.',
}, 'let mut items = vec![1, 2, 3]; let taken = std::mem::take(&mut items); format!("taken = {:?}, left = {:?}", taken, items)');

add('rc/clone', 'clone', RC, 'How Rc::clone works', 'Makes another owner of the same value by counting references; nothing is copied.', {
  call: 'let a = Rc::new(String::from("hi")); let b = Rc::clone(&a);', note: 'shared ownership', rows: [['"hi" (count 1)']], outs: ['a', 'b', 'count = 2'],
  intro: 'Rc puts the value on the heap together with a counter of how many owners it has.',
  steps: [
    ['a is the first owner: the count is 1.', 0, 'o0', 'count 1'],
    ['Rc::clone(&a) gives a second pointer to the same String and increases the count.', 0, 'o1,2', 'count 2'],
    ['When an owner goes out of scope the count goes down; at 0 the String is freed.', [], null, 'freed at 0'],
  ],
  result: '2', resultCap: 'Write Rc::clone(&a) rather than a.clone() so readers see that only a counter changes. Rc is single-threaded; Arc is the thread-safe version.',
}, 'let a = Rc::new(String::from("hi")); let b = Rc::clone(&a); let n = Rc::strong_count(&a); drop(b); n.to_string()');

add('rc/strong_count', 'strong_count', RC, 'How Rc::strong_count works', 'How many Rc owners share the value right now.', {
  call: 'Rc::strong_count(&a)', note: 'after one clone and one drop', rows: [['Rc::new', 'clone', 'drop']], outs: ['1', '2', '1'],
  intro: 'strong_count reads the counter that Rc keeps next to the value.',
  steps: [
    ['After Rc::new: 1.', 0, 'o0'],
    ['After Rc::clone: 2.', 1, 'o1'],
    ['After dropping the clone: 1 again.', 2, 'o2'],
  ],
  result: '1', resultCap: 'Mostly useful for learning and debugging; normal code rarely needs to look at the count.',
}, 'let a = Rc::new(5); let b = Rc::clone(&a); drop(b); Rc::strong_count(&a).to_string()');

add('refcell/borrow_mut', 'borrow_mut', REFCELL, 'How RefCell::borrow_mut works', 'Changes a value through a shared reference; the borrow rules are checked while the program runs.', {
  call: 'let c = RefCell::new(vec![1]); c.borrow_mut().push(2);', note: 'mutation through &RefCell', rows: [['RefCell [1]']], outs: ['[1, 2]'],
  intro: 'Normally you need &mut to change something. RefCell allows it through a shared & reference, and checks the rules at run time instead.',
  steps: [
    ['borrow_mut() hands out a mutable borrow and marks the RefCell as borrowed.', 0, null, 'mutably borrowed'],
    ['push(2) changes the Vec inside. When the borrow ends, the mark is cleared.', 0, 'o0', 'borrow released'],
    ['A second borrow_mut() while the first is still alive would panic: "already borrowed".', [], null, 'one writer at a time'],
  ],
  result: '[1, 2]', resultCap: 'Often combined as Rc<RefCell<T>>: shared ownership and mutation. try_borrow_mut returns an error instead of panicking.',
}, 'let c = RefCell::new(vec![1]); c.borrow_mut().push(2); let r = c.borrow(); d(&*r)');

add('refcell/borrow', 'borrow', REFCELL, 'How RefCell::borrow works', 'Reads the value; any number of readers, but not while someone is writing.', {
  call: 'let c = RefCell::new(5); let r1 = c.borrow(); let r2 = c.borrow();', note: 'many readers', rows: [['RefCell 5']], outs: ['r1 = 5', 'r2 = 5'],
  intro: 'borrow() gives a shared borrow, like &T, and counts the readers.',
  steps: [
    ['r1 borrows: 1 reader.', 0, 'o0'],
    ['r2 borrows too: 2 readers is fine.', 0, 'o1'],
    ['A borrow_mut() now would panic, because readers are active.', [], null, 'no writer while reading'],
  ],
  result: '5, 5', resultCap: 'These are the same rules the compiler enforces for & and &mut, only checked at run time.',
}, 'let c = RefCell::new(5); let r1 = c.borrow(); let r2 = c.borrow(); format!("{}, {}", *r1, *r2)');

add('cell/set', 'set', CELL, 'How Cell::set works', 'Replaces a Copy value inside a Cell through a shared reference.', {
  call: 'let c = Cell::new(1); c.set(5);', note: 'no borrow at all', rows: [['Cell 1']], outs: ['Cell 5'],
  intro: 'Cell never lends out a reference to its inside, so changing it through & is always safe.',
  steps: [
    ['set(5) overwrites the value.', 0, 'o0'],
    ['get() returns a copy of it: 5.', [], null, 'get() → 5'],
  ],
  result: '5', resultCap: 'Cell is for small Copy values like counters and flags; use RefCell for anything bigger.',
}, 'let c = Cell::new(1); c.set(5); c.get().to_string()');

add('box/new', 'new', BOX, 'How Box::new works', 'Moves a value to the heap and gives you an owning pointer to it.', {
  call: 'let b = Box::new(5);', note: 'stack pointer, heap value', rows: [['5']], outs: ['b → heap: 5'],
  intro: 'Box::new allocates room on the heap and moves the value there.',
  steps: [
    ['5 is moved to the heap.', 0, null, 'heap'],
    ['b is a pointer to it. When b goes out of scope, the heap memory is freed.', 0, 'o0'],
  ],
  result: '5', resultCap: 'Box is needed for recursive types (enum List { Cons(i32, Box<List>), Nil }) and for trait objects (Box<dyn Trait>).',
}, 'let b = Box::new(5); (*b).to_string()');

add('cmp/max', 'max', CMP, 'How cmp::max works', 'The larger of two values.', {
  call: 'std::cmp::max(3, 8)', note: 'any Ord type', rows: [nums([3, 8])], outs: ['8'],
  intro: 'max compares the two values and returns the larger.',
  steps: [
    ['3 < 8.', [0, 1]],
    ['8 is returned.', 1, 'o0'],
  ],
  result: '8', resultCap: 'With equal values it returns the second one. For floats use f64::max, because floats are not Ord.',
}, 'std::cmp::max(3, 8).to_string()');

add('cmp/min', 'min', CMP, 'How cmp::min works', 'The smaller of two values.', {
  call: 'std::cmp::min("pear", "apple")', note: 'strings compare alphabetically', rows: [['"pear"', '"apple"']], outs: ['"apple"'],
  intro: 'min returns the smaller value. For strings, "smaller" means earlier in alphabetical (byte) order.',
  steps: [
    ['"apple" < "pear" because a comes before p.', [0, 1], null, "'a' < 'p'"],
    ['"apple" is returned.', 1, 'o0'],
  ],
  result: '"apple"', resultCap: 'Uppercase letters sort before lowercase ones in this order: "Z" < "a".',
}, 'd(std::cmp::min("pear", "apple"))');

add('char/to_digit', 'to_digit', CHAR, 'How char::to_digit works', 'The number a digit character stands for, in a given base.', {
  call: "'7'.to_digit(10), 'f'.to_digit(16), 'x'.to_digit(10)", note: 'base 10 and base 16', rows: [["'7'", "'f'", "'x'"]], outs: ['Some(7)', 'Some(15)', 'None'],
  intro: "A char like '7' is not the number 7. to_digit converts it.",
  steps: [
    ["'7' in base 10 is 7.", 0, 'o0'],
    ["'f' in base 16 (hexadecimal) is 15.", 1, 'o1'],
    ["'x' is not a digit in base 10: None.", 2, { srcColor: 'danger', out: [2] }],
  ],
  result: 'Some(7), Some(15), None', resultCap: "Summing the digits of a string: s.chars().filter_map(|c| c.to_digit(10)).sum::<u32>().",
}, "format!(\"{:?}, {:?}, {:?}\", '7'.to_digit(10), 'f'.to_digit(16), 'x'.to_digit(10))");

add('char/from_digit', 'from_digit', CHAR, 'How char::from_digit works', 'The digit character for a number, in a given base.', {
  call: 'char::from_digit(7, 10), char::from_digit(12, 16)', note: 'the opposite of to_digit', rows: [['7', '12']], outs: ["Some('7')", "Some('c')"],
  intro: 'from_digit turns a small number into the character that writes it.',
  steps: [
    ["7 in base 10 is written '7'.", 0, 'o0'],
    ["12 in base 16 is written 'c'.", 1, 'o1'],
  ],
  result: "Some('7'), Some('c')", resultCap: 'A number too big for the base, like from_digit(10, 10), gives None.',
}, "format!(\"{:?}, {:?}\", char::from_digit(7, 10), char::from_digit(12, 16))");

add('char/is_alphabetic', 'is_alphabetic', CHAR, 'How char::is_alphabetic works', 'true for letters, in any alphabet.', {
  call: "'a'.is_alphabetic(), 'é'.is_alphabetic(), '1'.is_alphabetic()", note: 'Unicode letters', rows: [["'a'", "'é'", "'1'"]], outs: ['true', 'true', 'false'],
  intro: 'is_alphabetic follows Unicode, so letters with accents and other alphabets count.',
  steps: [
    ["'a' is a letter.", 0, 'o0'],
    ["'é' is a letter too.", 1, 'o1'],
    ["'1' is a digit, not a letter.", 2, { srcColor: 'danger', out: [2] }],
  ],
  result: 'true, true, false', resultCap: 'is_ascii_alphabetic only accepts a–z and A–Z.',
}, "format!(\"{}, {}, {}\", 'a'.is_alphabetic(), 'é'.is_alphabetic(), '1'.is_alphabetic())");

add('char/is_alphanumeric', 'is_alphanumeric', CHAR, 'How char::is_alphanumeric works', 'true for letters and digits.', {
  call: "\"a1-b\".chars().filter(|c| c.is_alphanumeric())", note: 'keep letters and digits', rows: [["'a'", "'1'", "'-'", "'b'"]], outs: ["'a'", "'1'", "'b'"],
  intro: 'is_alphanumeric is true for anything that is a letter or a number.',
  steps: [
    ["'a' and '1' pass.", [0, 1], 'o0,1'],
    ["'-' is punctuation: false.", 2, 'x'],
    ["'b' passes.", 3, 'o2'],
  ],
  result: '"a1b"', resultCap: 'Common for cleaning input: keep only letters and digits.',
}, 'd("a1-b".chars().filter(|c| c.is_alphanumeric()).collect::<String>())');

add('char/is_whitespace', 'is_whitespace', CHAR, 'How char::is_whitespace works', 'true for spaces, tabs, newlines and other blank characters.', {
  call: "' '.is_whitespace(), '\\n'.is_whitespace(), 'a'.is_whitespace()", note: 'all kinds of blank', rows: [["' '", "'\\n'", "'a'"]], outs: ['true', 'true', 'false'],
  intro: 'is_whitespace recognises every kind of blank character, not just the space.',
  steps: [
    ['A space is whitespace.', 0, 'o0'],
    ['A newline is too.', 1, 'o1'],
    ["'a' is not.", 2, { srcColor: 'danger', out: [2] }],
  ],
  result: 'true, true, false', resultCap: 'split_whitespace and trim use exactly this test.',
}, "format!(\"{}, {}, {}\", ' '.is_whitespace(), '\\n'.is_whitespace(), 'a'.is_whitespace())");

add('char/to_ascii_uppercase', 'to_ascii_uppercase', CHAR, 'How char::to_ascii_uppercase works', 'Uppercases a–z; every other character stays the same.', {
  call: "'q'.to_ascii_uppercase(), 'é'.to_ascii_uppercase()", note: 'ASCII only', rows: [["'q'", "'é'"]], outs: ["'Q'", "'é'"],
  intro: 'to_ascii_uppercase only touches the 26 ASCII letters and always returns exactly one char.',
  steps: [
    ["'q' becomes 'Q'.", 0, 'o0'],
    ["'é' is not ASCII, so it is returned unchanged.", 1, 'o1', 'not ASCII'],
  ],
  result: "'Q', 'é'", resultCap: "char::to_uppercase follows Unicode instead and can give several characters ('ß' → \"SS\").",
}, "format!(\"{:?}, {:?}\", 'q'.to_ascii_uppercase(), 'é'.to_ascii_uppercase())");

add('char/len_utf8', 'len_utf8', CHAR, 'How char::len_utf8 works', 'How many bytes the character takes in a UTF-8 string.', {
  call: "'a'.len_utf8(), 'é'.len_utf8(), '🦀'.len_utf8()", note: '1 to 4 bytes', rows: [["'a'", "'é'", "'🦀'"]], outs: ['1', '2', '4'],
  intro: 'UTF-8 uses 1 byte for ASCII and up to 4 bytes for other characters.',
  steps: [
    ["'a' is ASCII: 1 byte.", 0, 'o0'],
    ["'é': 2 bytes.", 1, 'o1'],
    ["The crab emoji: 4 bytes.", 2, 'o2'],
  ],
  result: '1, 2, 4', resultCap: 'This is why String::len() (bytes) and chars().count() (characters) can differ.',
}, "format!(\"{}, {}, {}\", 'a'.len_utf8(), 'é'.len_utf8(), '🦀'.len_utf8())");

add('char/is_ascii_digit', 'is_ascii_digit', CHAR, 'How char::is_ascii_digit works', 'true only for the characters 0 to 9.', {
  call: "\"a1b22\".chars().filter(char::is_ascii_digit).count()", note: 'count the digits', rows: [["'a'", "'1'", "'b'", "'2'", "'2'"]], outs: ['3'],
  intro: 'is_ascii_digit is true for 0–9 only.',
  steps: [
    ["'a' and 'b' are not digits.", [0, 2], 'x'],
    ["'1', '2' and '2' are: 3 digits.", [1, 3, 4], 'o0'],
  ],
  result: '3', resultCap: 'is_numeric also accepts other kinds of numerals (like Roman numeral characters); for parsing numbers, is_ascii_digit is usually what you want.',
}, '"a1b22".chars().filter(char::is_ascii_digit).count().to_string()');

add('f64/sqrt', 'sqrt', STD_F64, 'How f64::sqrt works', 'The square root; NaN for negative numbers.', {
  call: '16.0_f64.sqrt(), 2.0_f64.sqrt()', note: 'floats only', rows: [['16.0', '2.0']], outs: ['4', '1.4142135623730951'],
  intro: 'sqrt finds the number that, multiplied by itself, gives the input.',
  steps: [
    ['4 × 4 = 16, so the root of 16 is 4.', 0, 'o0'],
    ['The root of 2 is irrational; f64 gives the closest double: 1.4142135623730951.', 1, 'o1'],
  ],
  result: '4, 1.4142135623730951', resultCap: 'For integers, convert first: (n as f64).sqrt(). The square root of a negative number is NaN (not a number).',
}, 'format!("{}, {}", 16.0_f64.sqrt(), 2.0_f64.sqrt())');

add('f64/powi', 'powi', STD_F64, 'How f64::powi works', 'Raises a float to a whole-number power.', {
  call: '2.0_f64.powi(10)', note: '2 × 2 × … × 2, ten times', rows: [['2.0']], outs: ['1024'],
  intro: 'powi(10) multiplies the number by itself 10 times.',
  steps: [
    ['2, 4, 8, 16, 32 …', 0, null, '2^5 = 32'],
    ['… 64, 128, 256, 512, 1024.', 0, 'o0', '2^10 = 1024'],
  ],
  result: '1024', resultCap: 'powi takes an i32 exponent and is faster than powf, which allows fractional exponents.',
}, '2.0_f64.powi(10).to_string()');

add('f64/round', 'round', STD_F64, 'How f64::round works', 'Rounds to the nearest whole number; halves go away from zero.', {
  call: '2.5_f64.round(), 2.4_f64.round(), (-2.5_f64).round()', note: 'nearest whole number', rows: [['2.5', '2.4', '-2.5']], outs: ['3', '2', '-3'],
  intro: 'round picks the nearest integer. Exact halves are rounded away from zero.',
  steps: [
    ['2.5 is exactly halfway: away from zero, 3.', 0, 'o0'],
    ['2.4 is nearer to 2.', 1, 'o1'],
    ['-2.5 is halfway: away from zero means -3.', 2, 'o2'],
  ],
  result: '3, 2, -3', resultCap: 'The result is still an f64 (3.0). Use round_ties_even for banker\'s rounding (2.5 → 2).',
}, 'format!("{}, {}, {}", 2.5_f64.round(), 2.4_f64.round(), (-2.5_f64).round())');

add('f64/floor', 'floor', STD_F64, 'How f64::floor works', 'Rounds down to the next whole number (towards minus infinity).', {
  call: '2.7_f64.floor(), (-2.7_f64).floor()', note: 'always downwards', rows: [['2.7', '-2.7']], outs: ['2', '-3'],
  intro: 'floor goes down to the nearest integer below.',
  steps: [
    ['2.7 goes down to 2.', 0, 'o0'],
    ['-2.7 goes down to -3, not -2: down means more negative.', 1, 'o1', '-3 < -2.7'],
  ],
  result: '2, -3', resultCap: 'ceil rounds up instead; trunc just drops the fraction (-2.7 → -2).',
}, 'format!("{}, {}", 2.7_f64.floor(), (-2.7_f64).floor())');

add('f64/ceil', 'ceil', STD_F64, 'How f64::ceil works', 'Rounds up to the next whole number (towards plus infinity).', {
  call: '2.1_f64.ceil(), (-2.1_f64).ceil()', note: 'always upwards', rows: [['2.1', '-2.1']], outs: ['3', '-2'],
  intro: 'ceil goes up to the nearest integer above.',
  steps: [
    ['2.1 goes up to 3.', 0, 'o0'],
    ['-2.1 goes up to -2.', 1, 'o1', '-2 > -2.1'],
  ],
  result: '3, -2', resultCap: 'Useful for "how many pages for n items": (n as f64 / per_page as f64).ceil().',
}, 'format!("{}, {}", 2.1_f64.ceil(), (-2.1_f64).ceil())');

add('f64/trunc', 'trunc', STD_F64, 'How f64::trunc works', 'Drops the fractional part, towards zero.', {
  call: '2.7_f64.trunc(), (-2.7_f64).trunc()', note: 'cut off after the point', rows: [['2.7', '-2.7']], outs: ['2', '-2'],
  intro: 'trunc simply removes everything after the decimal point.',
  steps: [
    ['2.7 → 2.', 0, 'o0'],
    ['-2.7 → -2 (floor would give -3).', 1, 'o1'],
  ],
  result: '2, -2', resultCap: 'Casting with as i32 also truncates: -2.7 as i32 is -2.',
}, 'format!("{}, {}", 2.7_f64.trunc(), (-2.7_f64).trunc())');

add('f64/abs', 'abs', F64, 'How f64::abs works', 'The distance from zero: removes the minus sign.', {
  call: '(-3.5_f64).abs(), 3.5_f64.abs()', note: 'never negative', rows: [['-3.5', '3.5']], outs: ['3.5', '3.5'],
  intro: 'abs gives the size of the number without its sign.',
  steps: [
    ['-3.5 becomes 3.5.', 0, 'o0'],
    ['3.5 stays 3.5.', 1, 'o1'],
  ],
  result: '3.5, 3.5', resultCap: 'Comparing floats: (a - b).abs() < 1e-9 instead of a == b.',
}, 'format!("{}, {}", (-3.5_f64).abs(), 3.5_f64.abs())');

add('f64/max', 'max', F64, 'How f64::max works', 'The larger of two floats; ignores NaN.', {
  call: '1.5_f64.max(2.5), 1.5_f64.max(f64::NAN)', note: 'NaN loses', rows: [['1.5 vs 2.5', '1.5 vs NaN']], outs: ['2.5', '1.5'],
  intro: 'Floats are not Ord (because of NaN), so they have their own max.',
  steps: [
    ['2.5 is larger.', 0, 'o0'],
    ['If one side is NaN, the other number is returned.', 1, 'o1', 'NaN is ignored'],
  ],
  result: '2.5, 1.5', resultCap: 'The largest float in a list: v.iter().copied().fold(f64::NEG_INFINITY, f64::max).',
}, 'format!("{}, {}", 1.5_f64.max(2.5), 1.5_f64.max(f64::NAN))');

add('f64/clamp', 'clamp', F64, 'How f64::clamp works', 'Keeps a float inside a range.', {
  call: '1.7_f64.clamp(0.0, 1.0), (-0.2_f64).clamp(0.0, 1.0)', note: 'limit to 0.0 ..= 1.0', rows: [['1.7', '-0.2']], outs: ['1', '0'],
  intro: 'clamp returns the number if it is inside the range, otherwise the nearest end.',
  steps: [
    ['1.7 is above 1.0: it becomes 1.0.', 0, 'o0', 'too big'],
    ['-0.2 is below 0.0: it becomes 0.0.', 1, 'o1', 'too small'],
  ],
  result: '1, 0', resultCap: 'Handy for percentages, colours and volumes. clamp panics if min > max.',
}, 'format!("{}, {}", 1.7_f64.clamp(0.0, 1.0), (-0.2_f64).clamp(0.0, 1.0))');

add('range/contains', 'contains', RANGE, 'How Range::contains works', 'Checks whether a value lies inside the range.', {
  call: '(1..5).contains(&5), (1..=5).contains(&5)', note: '.. excludes the end, ..= includes it', rows: [['1..5', '1..=5']], outs: ['false', 'true'],
  intro: '1..5 goes up to but not including 5. 1..=5 includes 5.',
  steps: [
    ['5 is not in 1..5: the end is excluded.', 0, { srcColor: 'danger', out: [0] }],
    ['5 is in 1..=5.', 1, 'o1'],
  ],
  result: 'false, true', resultCap: 'Clearer than writing x >= 1 && x < 5 by hand.',
}, 'format!("{}, {}", (1..5).contains(&5), (1..=5).contains(&5))');

module.exports = list;
